from pathlib import Path

def organize(folder, mapping):
    for f in Path(folder).iterdir():
        if f.is_file() and f.suffix in mapping:
            dest = Path(folder) / mapping[f.suffix]
            dest.mkdir(exist_ok=True)
            print(f, "->", dest.name)

organize("downloads", {".jpg": "images", ".pdf": "docs"})

import time
from functools import wraps

def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        print(f"{func.__name__} took {time.time()-start:.4f}s")
        return result
    return wrapper

@timer
def slow_add(a, b):
    time.sleep(0.2)
    return a + b

print(slow_add(3, 4))

