import functools

def repeat(n):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*a, **k):
            return [fn(*a, **k) for _ in range(n)]
        return wrapper
    return decorator

@repeat(2)
def greet(name):
    return "hi " + name

print(greet("Ava"), greet.__name__)

